function Assert-ProDiskCase($config,$entries,[bool]$Early=$false) {
    $ErrorActionPreference='Stop';$all=@(Get-VM);$count=@($entries).Count;if($count -lt 1 -or $count -gt 2 -or (-not $Early -and $count -ne 2) -or $all.Count -ne $count){throw 'Only the bound case VM set is allowed'}
    $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$primary=Join-Path $root 'vms.json';$backup=Join-Path $root 'vms.backup.json';$ledger=[IO.File]::ReadAllText($primary)|ConvertFrom-Json
    if($ledger.version -ne 2 -or $ledger.ownerSid -ne $config.userSid -or @($ledger.records.psobject.Properties).Count -ne $count -or (Get-FileHash $primary).Hash -ne (Get-FileHash $backup).Hash){throw 'Disk case protected registration changed'}
    $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$exe=Join-Path $bin $artifact.brokerFile
    if($artifact.sourceDigest -ne $config.broker.sourceDigest -or $artifact.brokerSha256 -ne $config.broker.brokerSha256 -or (Get-FileHash $exe).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Disk case broker changed'}
    $identity=[Reflection.Assembly]::LoadFile($exe).GetType('MuDiskGrowthPolicy').GetMethod('FileIdentity');$observed=@()
    foreach($entry in $entries){
        $id=[string]$entry.id;$parsed=[guid]::Empty;if(-not [guid]::TryParseExact($id,'D',[ref]$parsed) -or $parsed.ToString('D') -cne $id){throw 'Canonical disk case identity required'}
        $name='mu-win-'+$id.Replace('-','');$vm=@($all|Where-Object{[string]$_.Id -eq [string]$entry.platformId});$record=$ledger.records.$id
        if($vm.Count -ne 1 -or $vm[0].Name -ne $name -or $vm[0].Notes -ne ('MuCodeSandbox Windows preview '+$name) -or [string]$vm[0].State -ne 'Off' -or $record.platformId -ne [string]$vm[0].Id -or $record.ownerSid -ne $config.userSid){throw 'Stopped disk case VM boundary changed'}
        $disk=[IO.Path]::GetFullPath((Join-Path $root ('vms/'+$id+'/disk.vhdx')));$drives=@(Get-VMHardDiskDrive -VM $vm[0]);if($drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $disk -or @(Get-VMSnapshot -VM $vm[0]).Count){throw 'Disk case storage boundary changed'}
        $vhd=Get-VHD -Path $disk;$fileIdentity=[string]$identity.Invoke($null,@($disk))
        if(($entry.originalDisk -and [string]$vhd.DiskIdentifier -ne $entry.originalDisk.diskIdentifier) -or [long]$vhd.Size -ne [long]$record.diskGiB*1GB){throw 'Disk case VHDX identity/capacity changed'}
        if($Early -and ($record.diskGrowth -or $record.diskGiB -ne 32 -or $entry.config.diskGiB -ne 32)){throw 'Only the initial untouched capacity can use early retry'}
        if($record.diskGrowth -and ($record.diskGrowth.diskIdentifier -ne [string]$vhd.DiskIdentifier -or $record.diskGrowth.fileIdentity -cne $fileIdentity)){throw 'Disk case growth journal changed'}
        $observed+=@{id=$id;platformId=[string]$vm[0].Id;diskIdentifier=([guid]$vhd.DiskIdentifier).ToString('D');fileIdentity=$fileIdentity;diskGiB=[int]$record.diskGiB;pending=[bool]$record.diskGrowth;role=$entry.role}
    }
    return @{registeredGuests=$count;copiesEqual=$true;disks=$observed}
}
function Invoke-ProDiskPhase($Session,[string]$Phase,$Guard,[string]$ProNonce,[string]$ScriptDirectory){
    $meta=$Guard.ReadCommand('disk-inputs.json')|ConvertFrom-Json
    if($meta.format -ne 1 -or $meta.proNonce -ne $ProNonce -or $meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.supportCase -notmatch '^[a-f0-9]{32}$' -or $meta.zipSha256 -notmatch '^[a-f0-9]{64}$'){throw 'Bound Pro disk case required'}
    if($Phase -eq 'disk-stage'){
        $Guard.PinInputFile([string]$meta.zip);if((Get-FileHash -LiteralPath $meta.zip).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Disk payload changed'}
        $earlyPolicy=(Get-Command Assert-ProDiskCase -CommandType Function).ScriptBlock.ToString()
        $admission=Invoke-Command -Session $Session -ArgumentList $meta,$earlyPolicy -ScriptBlock {param($meta,$policy) if(@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -and $_.ExecutablePath.StartsWith('C:\MuLab\',[StringComparison]::OrdinalIgnoreCase)) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-broker-*.exe'}).Count){throw 'Idle Pro fixture required before broker installation'};if($meta.replaceApp){$config=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$meta.caseId+'-config.json'))|ConvertFrom-Json;$old=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$meta.caseId+'-initial-result.json'))|ConvertFrom-Json;if($old.complete -ne $false -or @($old.quotas).Count -or (-not $meta.continuation -and (@($old.checks).Count -gt 1 -or @($old.checks|Where-Object{$_.passed -ne $true -or $_.name -ne "Two real original Linux VMs contain separate dev-owned Unicode canaries and start from confirmed stopped disks"}).Count -or @($old.rootProofs).Count -or $meta.broker.sourceDigest -ne $config.broker.sourceDigest))){throw 'Only the early stopped case may receive code replacement'};return (&([ScriptBlock]::Create($policy)) $config $old.entries (-not $meta.continuation))}elseif(@(Get-VM).Count){throw 'Fresh disk case requires an empty Pro guest'}}
        $archive='C:\MuLab\private\disk-'+$meta.caseId+'-'+[guid]::NewGuid().ToString('N')+'.zip';Copy-Item -LiteralPath $meta.zip -Destination $archive -ToSession $Session
        return Invoke-Command -Session $Session -ArgumentList $meta,$archive,$earlyPolicy,$admission -ScriptBlock {
            param($meta,$archive,$policy,$admission)
            $ErrorActionPreference='Stop';$target='C:\MuLab\disk-tools\'+$meta.caseId;$tools=$target;$oldConfig=$null
            if($meta.replaceApp){if($meta.revision -notmatch '^[a-f0-9]{32}$'){throw 'Code replacement revision required'};$oldConfig=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$meta.caseId+'-config.json'))|ConvertFrom-Json;$tools='C:\MuLab\disk-tools\pending-'+$meta.caseId+'-'+$meta.revision}elseif(Test-Path -LiteralPath $target){throw 'Existing disk case preserved'}
            if(Test-Path -LiteralPath $tools){throw 'Existing disk code preserved'}
            $support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$expected='C:\MuLab\image-tools\'+$meta.supportCase;$node=Join-Path $expected 'product/resources/node/node.exe'
            if($support.tools -ne $expected -or $support.image -ne ('C:\MuLab\images\image-'+$meta.supportCase+'.vhdx') -or (Get-FileHash -LiteralPath $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256 -or (Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Disk support/image/runtime changed'}
            Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive)
            try{[long]$size=0;if($zip.Entries.Count -gt 12000){throw 'Disk payload count exceeded'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$size+=$entry.Length;if($size -gt 2GB -or $entry.Length -gt 128MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('app/') -and -not $name.StartsWith('broker/') -and $name -notin @('pro-disk-client.mjs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe disk archive'}}}finally{$zip.Dispose()}
            [IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools);foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Disk payload digest changed'}}
            if($meta.replaceApp){$parent=[IO.Path]::GetFullPath('C:\MuLab\disk-tools');$before=Join-Path $parent ('before-'+$meta.caseId+'-'+$meta.revision);foreach($path in @($target,$tools,$before)){if([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($path)) -ne $parent){throw 'Disk code move escaped its fixed code directory'}};foreach($path in @('C:\','C:\MuLab',$parent,$target,$tools)){if((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Disk code reparse point rejected'}};if(Test-Path -LiteralPath $before){throw 'Existing disk code history preserved'};[IO.Directory]::Move($target,$before);try{[IO.Directory]::Move($tools,$target)}catch{if(-not(Test-Path -LiteralPath $target)){[IO.Directory]::Move($before,$target)};throw};$tools=$target}
            if($meta.broker.brokerFile -notmatch '^hv-broker-[a-f0-9]{16}\.exe$' -or $meta.broker.channelFile -notmatch '^hv-channel-[a-f0-9]{16}\.exe$' -or $meta.broker.sourceDigest -notmatch '^[a-f0-9]{64}$'){throw 'Fixed disk broker artifact required'}
            &([ScriptBlock]::Create([IO.File]::ReadAllText((Join-Path $tools 'broker/install-broker.ps1')))) -Broker (Join-Path $tools ('broker/'+$meta.broker.brokerFile)) -ExpectedBrokerHash $meta.broker.brokerSha256 -Channel (Join-Path $tools ('broker/'+$meta.broker.channelFile)) -ExpectedChannelHash $meta.broker.channelSha256 -SourceDigest $meta.broker.sourceDigest
            $config=@{caseId=$meta.caseId;proNonce=$meta.proNonce;tools=$tools;app=(Join-Path $tools 'app');support=$expected;node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$meta.imageSha256;files=$meta.files;broker=$meta.broker;userSid=(Get-LocalUser MuLabUser).SID.Value}
            if($oldConfig -and $oldConfig.retryEntries){$config.retryEntries=@($oldConfig.retryEntries)};if($meta.continuation){$failed=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$meta.caseId+'-initial-result.json'))|ConvertFrom-Json;$config.continueInitial=@($failed.entries);$config.nativeUpgradedFrom=$oldConfig.broker}
            if($meta.continuation){$after=&([ScriptBlock]::Create($policy)) $config $config.continueInitial;foreach($disk in $admission.disks){$matched=@($after.disks|Where-Object id -eq $disk.id);if($matched.Count -ne 1){throw 'Disk code update changed the original VM set'};foreach($field in @('platformId','diskIdentifier','fileIdentity','diskGiB','pending')){if($matched[0].$field -cne $disk.$field){throw 'Disk code update changed original disk identities or intent'}}}}
            [IO.File]::WriteAllText(('C:\MuLab\approved\disk-'+$meta.caseId+'-config.json'),($config|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));return @{complete=$true;staged=$true;brokerInstalled=$true;vmCreated=$false}
        }
    }
    $policy=(Get-Command Assert-ProDiskCase -CommandType Function).ScriptBlock.ToString()
    if($Phase -in @('disk-refresh','disk-refresh-continue')){
        $source=Join-Path $ScriptDirectory 'pro-disk-client.mjs';$Guard.PinInputFile($source);$hash=(Get-FileHash -LiteralPath $source).Hash.ToLowerInvariant()
        $plan=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$policy,($Phase -eq 'disk-refresh-continue') -ScriptBlock {
            param($caseId,$policy,$continuing)
            $config=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$caseId+'-config.json'))|ConvertFrom-Json;$prefix='C:\MuLab\public\disk-'+$caseId+'-initial';$old=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$caseId+'-initial-result.json'))|ConvertFrom-Json;$owner=[IO.File]::ReadAllText($prefix+'-owner.json')|ConvertFrom-Json
            if($old.complete -ne $false -or (-not $continuing -and (@($old.checks).Count -gt 1 -or @($old.checks|Where-Object{$_.passed -ne $true -or $_.name -ne "Two real original Linux VMs contain separate dev-owned Unicode canaries and start from confirmed stopped disks"}).Count -or @($old.rootProofs).Count)) -or @($old.quotas).Count -or $old.pid -ne $owner.pid -or $old.nonce -cne $owner.nonce -or $old.caseId -ne $caseId -or (Get-ScheduledTask -TaskName ('MuPro-disk-'+$caseId+'-initial') -ErrorAction SilentlyContinue)){throw 'Only an early terminal failed disk case can refresh'}
            if(@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -and $_.ExecutablePath.StartsWith('C:\MuLab\',[StringComparison]::OrdinalIgnoreCase)) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-broker-*.exe'}).Count){throw 'Disk actors remain live'}
            foreach($entry in $old.entries){if(-not $entry.confirmedOff -or $entry.removed -or $entry.role -notin @('A','B')){throw 'Original stopped disk set required'}}
            $observed=&([ScriptBlock]::Create($policy)) $config $old.entries (-not $continuing)
            if((Get-FileHash -LiteralPath (Join-Path $config.tools 'pro-disk-client.mjs')).Hash.ToLowerInvariant() -ne $config.files.'pro-disk-client.mjs'){throw 'Original disk diagnostic source changed'}
            $history='C:\MuLab\private\disk-history-'+$caseId+'-'+[guid]::NewGuid().ToString('N');[IO.Directory]::CreateDirectory($history)|Out-Null;[IO.File]::Copy((Join-Path $config.tools 'pro-disk-client.mjs'),(Join-Path $history 'client.mjs'))
            [IO.File]::WriteAllText((Join-Path $history 'observed-stopped-disks.json'),($observed|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));[IO.File]::Copy(('C:\MuLab\approved\disk-'+$caseId+'-initial-result.json'),(Join-Path $history 'approved-result.json'))
            foreach($name in @('owner','progress','ready','result')){$from=[IO.Path]::GetFullPath($prefix+'-'+$name+'.json');$to=[IO.Path]::GetFullPath((Join-Path $history ($name+'.json')));if([IO.Path]::GetDirectoryName($from) -ne 'C:\MuLab\public' -or [IO.Path]::GetDirectoryName($to) -ne $history){throw 'Disk history move escaped its fixed directories'};if(Test-Path -LiteralPath $from){[IO.File]::Move($from,$to)}}
            $retry=@();foreach($entry in $old.entries){$actual=@($observed.disks|Where-Object id -eq $entry.id)[0];if(-not $continuing){$entry|Add-Member -NotePropertyName originalDisk -NotePropertyValue (@{platformId=$actual.platformId;diskIdentifier=$actual.diskIdentifier;actualGiB=32;registeredGiB=32;pending=$false;fromGiB=32;targetGiB=32}) -Force};$retry+=$entry}
            return @{tools=$config.tools;retry=$retry;history=$history;continuing=$continuing}
        }
        if($plan.tools -ne ('C:\MuLab\disk-tools\'+$meta.caseId)){throw 'Disk diagnostic destination changed'};Copy-Item -LiteralPath $source -Destination (Join-Path $plan.tools 'pro-disk-client.mjs') -ToSession $Session -Force
        return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$hash,$plan.retry,$plan.continuing -ScriptBlock {param($caseId,$hash,$retry,$continuing) $file='C:\MuLab\approved\disk-'+$caseId+'-config.json';$config=[IO.File]::ReadAllText($file)|ConvertFrom-Json;if((Get-FileHash -LiteralPath (Join-Path $config.tools 'pro-disk-client.mjs')).Hash.ToLowerInvariant() -ne $hash){throw 'Disk diagnostic refresh differs'};$config.files.'pro-disk-client.mjs'=$hash;if($continuing){$config|Add-Member -NotePropertyName continueInitial -NotePropertyValue @($retry) -Force}else{$config|Add-Member -NotePropertyName retryEntries -NotePropertyValue @($retry) -Force};[IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));return @{complete=$true;diagnosticUpdated=$true;originalDisksPreserved=$true}}
    }
    return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$Phase,$policy -ScriptBlock {
        param($caseId,$phase,$policy)
        $ErrorActionPreference='Stop';$base='C:\MuLab\public\disk-'+$caseId;$config=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$caseId+'-config.json'))|ConvertFrom-Json
        if($config.caseId -ne $caseId -or $config.tools -ne ('C:\MuLab\disk-tools\'+$caseId)){throw 'Disk case config changed'}
        if($phase -eq 'disk-snapshot'){$failed=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$caseId+'-initial-result.json'))|ConvertFrom-Json;if($failed.complete -ne $false){throw 'Terminal failed original case required'};$observed=&([ScriptBlock]::Create($policy)) $config $failed.entries;return @{complete=$true;scope='independent-stopped-original-disk-observation';observed=$observed}}
        if($phase -eq 'disk-inspect'){
            $reports=@();foreach($step in @('initial','resume')){foreach($kind in @('owner','progress','ready','review','result')){$file=$base+'-'+$step+'-'+$kind+'.json';if(Test-Path -LiteralPath $file){$reports+=@{step=$step;kind=$kind;value=([IO.File]::ReadAllText($file)|ConvertFrom-Json)}}}}
            $logs=@();foreach($step in @('initial','resume')){$file=$base+'-'+$step+'-client.log';if(Test-Path -LiteralPath $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{if($stream.Length -gt 8192){$stream.Position=$stream.Length-8192};$reader=[IO.StreamReader]::new($stream);$text=$reader.ReadToEnd();$logs+=@{step=$step;tail=$text.Substring([Math]::Max(0,$text.Length-5000))}}finally{$stream.Dispose()}}}
            $hashes=@{};foreach($name in @('server/platform/windows/runtime','server/platform/windows/manager','server/platform/windows/service','server/platform/windows/broker','server/platform/windows/disk-growth','shared/windows-disk')){$file='dist-server/'+$name+'.js';$hashes[$file]=(Get-FileHash -LiteralPath (Join-Path $config.app $file)).Hash.ToLowerInvariant()}
            return @{complete=$true;reports=$reports;logs=$logs;artifactHashes=$hashes;clientSha256=(Get-FileHash -LiteralPath (Join-Path $config.tools 'pro-disk-client.mjs')).Hash.ToLowerInvariant();imageSha256=(Get-FileHash -LiteralPath $config.image).Hash.ToLowerInvariant();broker=$config.broker;nodes=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -eq $config.node}|Select-Object ProcessId,CreationDate,CommandLine);nested=@(Get-VM|ForEach-Object{@{id=[string]$_.Id;name=$_.Name;state=[string]$_.State}})}
        }
        $step=if($phase -eq 'disk-run'){'initial'}elseif($phase -eq 'disk-resume'){'resume'}else{throw 'Unknown disk phase'}
        $prefix=$base+'-'+$step;$ownerFile=$prefix+'-owner.json';$resultFile=$prefix+'-result.json';$task='MuPro-disk-'+$caseId+'-'+$step
        if((Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue) -or (Test-Path -LiteralPath $ownerFile) -or (Test-Path -LiteralPath $resultFile)){throw 'Existing disk phase must be inspected'}
        if($step -eq 'initial'){if($config.continueInitial){&([ScriptBlock]::Create($policy)) $config $config.continueInitial|Out-Null}elseif($config.retryEntries){&([ScriptBlock]::Create($policy)) $config $config.retryEntries $true|Out-Null}elseif(@(Get-VM).Count){throw 'Initial disk phase requires an empty guest'}}else{$old=[IO.File]::ReadAllText(('C:\MuLab\approved\disk-'+$caseId+'-initial-crash.json'))|ConvertFrom-Json;if(-not $old.complete -or -not $old.controllerExitConfirmed -or -not $old.brokerExitConfirmed){throw 'Confirmed original controller loss required'};&([ScriptBlock]::Create($policy)) $config $old.ready.entries|Out-Null}
        $client=Join-Path $config.tools 'pro-disk-client.mjs';if((Get-FileHash -LiteralPath $client).Hash.ToLowerInvariant() -ne $config.files.'pro-disk-client.mjs' -or (Get-FileHash -LiteralPath $config.node).Hash.ToLowerInvariant() -ne $config.nodeSha256){throw 'Disk client/runtime changed'}
        $launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$config.node+''' --no-warnings '''+$client+''' '+$caseId+' '+$step+' *> '''+$prefix+'-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch))
        $principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1)) -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
        Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
        $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path -LiteralPath $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Disk phase owner not observed; retain task'};Start-Sleep -Milliseconds 250}
        $owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
        if($owner.caseId -ne $caseId -or $owner.phase -ne $step -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne $config.node -or $actor.CommandLine -notlike ('*'+$client+'*'+$caseId+'*'+$step+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $config.userSid){throw 'Disk owner process binding changed'}
        $handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$installed=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $installed.brokerFile
        if($installed.sourceDigest -ne $config.broker.sourceDigest -or (Get-FileHash -LiteralPath $broker).Hash.ToLowerInvariant() -ne $config.broker.brokerSha256){throw 'Disk installed broker changed'}
        $agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ('C:\MuLab\private\disk-'+$caseId+'-'+$step+'-broker-out.log') -RedirectStandardError ('C:\MuLab\private\disk-'+$caseId+'-'+$step+'-broker-error.log') -PassThru;$null=$agent.Handle;$until=[DateTime]::UtcNow.AddMinutes(30)
        do{
            if($step -eq 'initial' -and (Test-Path -LiteralPath ($prefix+'-ready.json'))){
                $ready=[IO.File]::ReadAllText($prefix+'-ready.json')|ConvertFrom-Json;if($ready.caseId -ne $caseId -or $ready.pid -ne $owner.pid -or $ready.nonce -cne $owner.nonce -or $ready.scope -ne 'ready-for-controlled-controller-loss'){throw 'Disk controller-loss barrier changed'}
                $before=&([ScriptBlock]::Create($policy)) $config $ready.entries
                $a=@($before.disks|Where-Object role -eq 'A');if($a.Count -ne 1 -or -not $a[0].pending -or $a[0].diskGiB -ne 48){throw 'Expected original pending growth not observed'}
                Stop-Process -InputObject $handle -Force;if(-not $handle.WaitForExit(15000)){throw 'Disk controller exit unconfirmed'};if(-not $agent.WaitForExit(45000)){throw 'Independent disk broker exit unconfirmed'}
                $after=&([ScriptBlock]::Create($policy)) $config $ready.entries
                foreach($disk in $before.disks){$same=@($after.disks|Where-Object id -eq $disk.id);if($same.Count -ne 1){throw 'Controller loss changed the disk set'};foreach($field in @('platformId','diskIdentifier','fileIdentity','diskGiB','pending','role')){if($same[0].$field -cne $disk.$field){throw 'Controller loss changed stopped disk identities or intent'}}}
                $receipt=@{complete=$true;scope='independently-confirmed-controller-loss-with-pending-growth';caseId=$caseId;pid=$owner.pid;nonce=$owner.nonce;controllerExitConfirmed=$true;brokerExitConfirmed=$true;ready=$ready;before=$before;after=$after}
                [IO.File]::WriteAllText(('C:\MuLab\approved\disk-'+$caseId+'-initial-crash.json'),($receipt|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $receipt
            }
            if(Test-Path -LiteralPath $resultFile){if(-not $handle.WaitForExit(15000)){throw 'Disk owner terminal receipt exists but its process is still live'};if(-not $agent.WaitForExit(45000)){throw 'Disk broker exit remains unconfirmed'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Disk terminal receipt changed'};[IO.File]::WriteAllText(('C:\MuLab\approved\disk-'+$caseId+'-'+$step+'-result.json'),($result|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result}
            if($handle.HasExited){throw 'Disk owner exited without a result; retain original resources'};if([DateTime]::UtcNow -gt $until){throw 'Disk phase is still unconfirmed; inspect its existing owner'};Start-Sleep -Milliseconds 250
        }while($true)
    }
}
